const input = $json.body ?? $json;
if (!input.deadline) {
  return [{ json: { error: 'deadline is required as an ISO 8601 timestamp with timezone', humanReviewRequired: true } }];
}

const now = input.now ? new Date(input.now) : new Date();
const deadline = new Date(input.deadline);
if (Number.isNaN(deadline.getTime())) {
  return [{ json: { error: 'deadline is not a valid date', suppliedDeadline: input.deadline, humanReviewRequired: true } }];
}

const millisecondsPerDay = 24 * 60 * 60 * 1000;
const daysRemaining = Math.ceil((deadline.getTime() - now.getTime()) / millisecondsPerDay);
const exactWaves = [30, 21, 14, 7, 3, 1, 0];
const waveDue = exactWaves.includes(daysRemaining) ? daysRemaining : null;
let stage = 'education';
if (daysRemaining <= 21 && daysRemaining > 7) stage = 'conversion';
if (daysRemaining <= 7 && daysRemaining >= 0) stage = 'deadline';
if (daysRemaining < 0) stage = 'closed';

const actions = {
  education: ['Explain eligibility and client validation', 'Publish evidence checklist', 'Promote nomination clinic and assessor recruitment'],
  conversion: ['Segment started versus completed nominations', 'Draft incomplete-submission reminders', 'Check missing customer assessments'],
  deadline: ['Use exact closing timestamp and timezone', 'Send only to consented relevant audiences', 'Offer submission support and suppress completed records'],
  closed: ['Stop nomination calls', 'Reconcile attribution and funnel metrics', 'Publish thank-you and next-stage dates']
};

return [{ json: {
  campaign: input.campaign ?? 'PCotY 2027',
  now: now.toISOString(),
  deadline: deadline.toISOString(),
  daysRemaining,
  stage,
  waveDue,
  actions: actions[stage],
  humanReviewRequired: true,
  warning: 'This workflow creates a decision packet only. It does not send or publish messages.'
} }];
